// Label + context from the site, icons from the theme's REST endpoint
const body = $('Webhook').first().json.body ?? {};
const icons = ($json.data ?? []).map(i => ({ name: String(i.name), description: String(i.description ?? '') }));

return [{
  json: {
    text: String(body.text ?? '').trim(),
    context: String(body.context ?? '').trim(),
    icons,
  },
}];

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "icon": { "type": "string", "description": "Name of the chosen icon, verbatim from the list" },
    "confidence": { "type": "number", "minimum": 0, "maximum": 1 },
    "reason": { "type": "string" }
  },
  "required": ["icon", "confidence", "reason"]
}

parameters.jsCode:
// Only names of the theme's list count; the site checks again and uses its own fallback
const cfg = $('Prepare').first().json;
const out = $json.output ?? {};
const wanted = String(out.icon ?? '').trim().toLowerCase();
const hit = cfg.icons.find(i => i.name.toLowerCase() === wanted);

return [{
  json: {
    text: cfg.text,
    icon: hit ? hit.name : null,
    matched: Boolean(hit),
    confidence: hit ? Number(out.confidence ?? 0) : 0,
    reason: String(out.reason ?? ''),
  },
}];
